G = load()

# Very careful check of my submitted result
test_in = G['Test input']

def transform(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    rows_with_2s = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                rows_with_2s.add(r)

    if not rows_with_2s:
        return result

    rows_with_2s = sorted(rows_with_2s)
    print(f"rows_with_2s = {rows_with_2s}")
    mid_row = (rows_with_2s[0] + rows_with_2s[-1]) // 2
    print(f"mid_row = ({rows_with_2s[0]} + {rows_with_2s[-1]}) // 2 = {mid_row}")

    for c in range(w):
        if mid_row < len(result):
            result[mid_row][c] = 3

    return result

result = transform(test_in)

print("\nResult as list of lists:")
for r, row in enumerate(result):
    print(f"Row {r}: {row}")

# Also print as code
print("\nAs json:")
print(json.dumps(result))

